import{_ as t,r as e,o,c as p,b as s,d as n,e as c,a as l}from"./app-d475bf24.js";const i={},u=l(`<p>在Android系统中，后台进程注册的<code>ContentObserver</code>会有一个延迟回调机制，通常延迟10秒左右。这种机制的设计是为了优化系统资源，减少后台进程频繁监听数据变化带来的资源消耗。。</p><h2 id="实现原因与机制" tabindex="-1"><a class="header-anchor" href="#实现原因与机制" aria-hidden="true">#</a> 实现原因与机制</h2><p>在Android的<code>ActivityManagerService</code>源码中，系统将前台和后台进程分别管理。对于后台进程，系统会降低其优先级，限制频繁的资源访问，尤其是数据变化监听。Android系统会检查当前进程的状态（前台或后台），对后台进程设置延迟调用，机制如下：</p><ol><li><strong>系统判定进程状态</strong>：当应用注册<code>ContentObserver</code>时，系统会根据该应用的进程状态决定回调的处理方式。如果是后台进程，系统会标记延迟回调。</li><li><strong>延迟策略</strong>：对于后台进程，<code>ContentObserver</code>的回调会被延迟10秒左右。延迟时长并不是固定的10秒，而是根据系统负载动态调整。延迟时间的存在让后台进程无法频繁获取数据变化，节省系统资源。</li><li><strong>触发机制</strong>：系统会在每隔一段时间后检查<code>ContentObserver</code>的注册状态，如果观察的URI在10秒内没有发生进一步的变化，则触发延迟回调。</li></ol><h2 id="相关源码分析" tabindex="-1"><a class="header-anchor" href="#相关源码分析" aria-hidden="true">#</a> 相关源码分析</h2><p><code>ContentObserver</code>的延迟机制在<code>ContentService</code>源码中有所体现。以下是相关的源码片段示例：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// frameworks/base/core/java/android/content/ContentService.java</span>

 <span class="token doc-comment comment">/**
     * Delay to apply to content change notifications dispatched to apps running
     * in the background. This is used to help prevent stampeding when the user
     * is performing CPU/RAM intensive foreground tasks, such as when capturing
     * burst photos.
     */</span>
    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token keyword">long</span> <span class="token constant">BACKGROUND_OBSERVER_DELAY</span> <span class="token operator">=</span> <span class="token number">10</span> <span class="token operator">*</span> <span class="token class-name">DateUtils</span><span class="token punctuation">.</span><span class="token constant">SECOND_IN_MILLIS</span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">dispatch</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> collected<span class="token punctuation">.</span><span class="token function">size</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token keyword">final</span> <span class="token class-name">Key</span> key <span class="token operator">=</span> collected<span class="token punctuation">.</span><span class="token function">keyAt</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token keyword">final</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Uri</span><span class="token punctuation">&gt;</span></span> value <span class="token operator">=</span> collected<span class="token punctuation">.</span><span class="token function">valueAt</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span><span class="token punctuation">;</span>

                <span class="token keyword">final</span> <span class="token class-name">Runnable</span> task <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
                    <span class="token keyword">try</span> <span class="token punctuation">{</span>
                        key<span class="token punctuation">.</span>observer<span class="token punctuation">.</span><span class="token function">onChangeEtc</span><span class="token punctuation">(</span>key<span class="token punctuation">.</span>selfChange<span class="token punctuation">,</span>
                                value<span class="token punctuation">.</span><span class="token function">toArray</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Uri</span><span class="token punctuation">[</span>value<span class="token punctuation">.</span><span class="token function">size</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">,</span> key<span class="token punctuation">.</span>flags<span class="token punctuation">,</span> key<span class="token punctuation">.</span>userId<span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">RemoteException</span> ignored<span class="token punctuation">)</span> <span class="token punctuation">{</span>
                    <span class="token punctuation">}</span>
                <span class="token punctuation">}</span><span class="token punctuation">;</span>

                <span class="token comment">// Immediately dispatch notifications to foreground apps that</span>
                <span class="token comment">// are important to the user; all other background observers are</span>
                <span class="token comment">// delayed to avoid stampeding</span>
                <span class="token keyword">final</span> <span class="token keyword">boolean</span> noDelay <span class="token operator">=</span> <span class="token punctuation">(</span>key<span class="token punctuation">.</span>flags <span class="token operator">&amp;</span> <span class="token class-name">ContentResolver</span><span class="token punctuation">.</span><span class="token constant">NOTIFY_NO_DELAY</span><span class="token punctuation">)</span> <span class="token operator">!=</span> <span class="token number">0</span><span class="token punctuation">;</span>
                <span class="token keyword">final</span> <span class="token keyword">int</span> procState <span class="token operator">=</span> <span class="token class-name">LocalServices</span><span class="token punctuation">.</span><span class="token function">getService</span><span class="token punctuation">(</span><span class="token class-name">ActivityManagerInternal</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span>
                        <span class="token punctuation">.</span><span class="token function">getUidProcessState</span><span class="token punctuation">(</span>key<span class="token punctuation">.</span>uid<span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token keyword">if</span> <span class="token punctuation">(</span>procState <span class="token operator">&lt;=</span> <span class="token class-name">ActivityManager</span><span class="token punctuation">.</span><span class="token constant">PROCESS_STATE_IMPORTANT_FOREGROUND</span> <span class="token operator">||</span> noDelay<span class="token punctuation">)</span> <span class="token punctuation">{</span>
                    task<span class="token punctuation">.</span><span class="token function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span>
                    <span class="token class-name">BackgroundThread</span><span class="token punctuation">.</span><span class="token function">getHandler</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">postDelayed</span><span class="token punctuation">(</span>task<span class="token punctuation">,</span> <span class="token constant">BACKGROUND_OBSERVER_DELAY</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
            <span class="token punctuation">}</span>
        <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>可以看出，有两个或条件会导致通知回调延迟10秒钟：</p><ul><li><strong>后台进程</strong>：procState &gt; ActivityManager.PROCESS_STATE_IMPORTANT_FOREGROUND, 也就是监听的进程为后台进程；</li><li><strong>key.flags不为noDelay</strong>：发起通知的时候，会传进来一个int flags参数，如果该参数 (key.flags &amp; ContentResolver.NOTIFY_NO_DELAY) != 0，则不会延迟调用。</li></ul><h2 id="实际开发过程中遇到的相关问题" tabindex="-1"><a class="header-anchor" href="#实际开发过程中遇到的相关问题" aria-hidden="true">#</a> 实际开发过程中遇到的相关问题</h2><p>在应用实际运行中，这一延迟会导致后台应用对数据变化的反应较慢。这种机制在以下场景中较为显著，比如后台进程监控的实时数据更新只能每隔10秒左右收到一次回调。典型的例子，就是添加到桌面的小部件相关的AppWidgetProvider，一般都运行在跟后台进程中，但是小部件基本都显示在桌面上。其监听的数据变化晚10秒的话，会导致用户感知到的数据刷新晚10秒。这样很大程度上被认为属于软件故障。</p><h2 id="应对方案" tabindex="-1"><a class="header-anchor" href="#应对方案" aria-hidden="true">#</a> 应对方案</h2><p>为了降低这种延迟带来的影响，可以尝试以下策略：</p><ol><li><strong>前台服务</strong>：通过启动前台服务（Foreground Service），使应用在后台时也保持前台进程的优先级，从而即时接收数据变化的回调。但是随着Android系统版本的眼睛，后台进程通过启动前台服务使其变为前台进程的方法受到系统越来越多的限制甚至会引发报错。</li><li><strong>JobScheduler和WorkManager</strong>：在后台场景下，采用JobScheduler或WorkManager来实现数据变化的处理，而非实时监听。</li><li><strong>BroadcastReceiver</strong>：结合系统广播监听数据变化，适用于一些系统设置变化的场景。</li><li><strong>修改ROM代码</strong>：对于可以修改ROM代码的开发人员，也可以在通知变化的地方修改flags为NO_DELAY或者在以上源码中增加白名单，使得特定包名的应用看了一绕过系统原生的延迟机制。</li></ol><h3 id="不想修改源码的方案" tabindex="-1"><a class="header-anchor" href="#不想修改源码的方案" aria-hidden="true">#</a> 不想修改源码的方案</h3><p>在修改Provider值后加上使用notifyChange主动通知并添加<code>ContentResolver.NOTIFY_NO_DELAY</code>的flag</p><p>但是在<code>android/content/ContentResolver.java</code>中，NOTIFY_NO_DELAY是隐藏API</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token keyword">int</span> <span class="token constant">NOTIFY_NO_DELAY</span> <span class="token operator">=</span> <span class="token number">1</span><span class="token operator">&lt;&lt;</span><span class="token number">15</span><span class="token punctuation">;</span> <span class="token comment">//可手动定义</span>
<span class="token function">getContext</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getContentResolver</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">notifyChange</span><span class="token punctuation">(</span>uri<span class="token punctuation">,</span> <span class="token keyword">null</span><span class="token punctuation">,</span> <span class="token constant">NOTIFY_NO_DELAY</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结" aria-hidden="true">#</a> 总结</h2><p>Android后台进程中<code>ContentObserver</code>延迟回调机制是为了系统资源优化而设计。它确保后台应用不会频繁监听数据变化，从而降低系统负载。理解该机制有助于开发者优化应用在后台的数据同步策略，提升应用的系统兼容性和资源管理效率。</p>`,20),r={href:"https://blog.csdn.net/wudexiaoade2008/article/details/143259312",target:"_blank",rel:"noopener noreferrer"};function d(k,v){const a=e("ExternalLinkIcon");return o(),p("div",null,[u,s("p",null,[n("本文转自 "),s("a",r,[n("https://blog.csdn.net/wudexiaoade2008/article/details/143259312"),c(a)]),n("，如有侵权，请联系删除。")])])}const h=t(i,[["render",d],["__file","houtaijinchengzhongdeContentObserveryanchihuidiaowan10miaozhong.html.vue"]]);export{h as default};
